// Reduziert das Fehlerobjekt von n8n auf das, was der Betrieb braucht: welcher
// Workflow, welche Ausführung, welcher Node, welche Meldung. Keine Nutzdaten der
// Akte — die stehen in der Ausführung selbst und gehören nicht in ein Protokoll,
// das breiter gelesen wird (docs/DATENSCHUTZ.md).
const e = $input.first().json;
return [{
  json: {
    workflow_name: e.workflow?.name ?? null,
    workflow_id: e.workflow?.id ?? null,
    execution_id: e.execution?.id ?? null,
    node_name: e.execution?.lastNodeExecuted ?? null,
    meldung: e.execution?.error?.message ?? String(e.execution?.error ?? 'unbekannt'),
    aufgetreten_am: new Date().toISOString(),
    ausfuehrung_url: e.execution?.url ?? null,
  },
}];
